module.cms_data.fix_snippet:
# nginx
location = /xmlrpc.php {
    deny all;
}
location ~* /(readme\.html|license\.txt|readme\.txt|changelog\.txt|release_notes\.txt)$ {
    deny all;
}

# Apache
<Files "xmlrpc.php">
    Require all denied
</Files>
<FilesMatch "(?i)^(readme\.html|license\.txt|readme\.txt|changelog\.txt|release_notes\.txt)$">
    Require all denied
</FilesMatch>

# WordPress
remove_action('wp_head', 'wp_generator');
add_filter('rest_endpoints', function ($endpoints) {
    if (!is_user_logged_in()) {
        unset($endpoints['/wp/v2/users']);
        unset($endpoints['/wp/v2/users/(?P<id>[\d]+)']);
    }
    return $endpoints;
});
